(function(){"use strict";const l="rk_auth_tokens",n="rk_context";window.RKAuth={setToken:function(e,t,o){o=o||86400;try{var r=this.getAll()||{};r[e+"_token"]=t,r[e+"_expires_at"]=Date.now()+o*1e3,localStorage.setItem(l,JSON.stringify(r)),localStorage.setItem(n,e)}catch(s){console.error("[RKAuth] Failed to save token:",s.message)}},getToken:function(e){try{var t=this.getAll();if(!t)return null;var o=t[e+"_token"],r=t[e+"_expires_at"];return r&&Date.now()>r?(this.removeToken(e),null):o||null}catch(s){return console.error("[RKAuth] Failed to get token:",s.message),null}},getAll:function(){try{var e=localStorage.getItem(l);return e?JSON.parse(e):null}catch(t){return console.error("[RKAuth] Failed to parse tokens:",t.message),null}},removeToken:function(e){try{var t=this.getAll()||{};delete t[e+"_token"],delete t[e+"_expires_at"],Object.keys(t).length===0?(localStorage.removeItem(l),localStorage.removeItem(n)):localStorage.setItem(l,JSON.stringify(t))}catch(o){console.error("[RKAuth] Failed to remove token:",o.message)}},getContext:function(){return localStorage.getItem(n)||null},logout:function(){try{localStorage.removeItem(l),localStorage.removeItem(n),sessionStorage.clear()}catch(e){console.error("[RKAuth] Failed to logout:",e.message)}},isAuthenticated:function(e){return!!this.getToken(e)}}})();
